import type { NextConfig } from "next";
import path from "node:path";
import { withSentryConfig } from "@sentry/nextjs";

const nextConfig: NextConfig = {
  reactStrictMode: true,
  // Standalone output bundles only the files needed to run the server
  // into .next/standalone/, producing a ~100MB Docker image instead of
  // the ~1GB you'd get copying the full repo + node_modules. Required
  // for the Railway deployment Dockerfile.
  output: "standalone",
  turbopack: {
    root: path.resolve(__dirname),
  },
  images: {
    remotePatterns: [
      {
        protocol: "https",
        hostname: "pub-bb2e103a32db4e198524a2e9ed8f35b4.r2.dev",
      },
      {
        protocol: "https",
        hostname: "zkzontawprihrzpayeam.supabase.co",
      },
      {
        protocol: "https",
        hostname: "*.supabase.co",
      },
    ],
  },
  // TEMPORARY during BUBS schema migration (2026-04-11):
  // The frontend still has ~50 TSC errors because views in the new
  // BUBS compat layer return `never` type for updates (Postgres views
  // without writable triggers). Runtime works because the views +
  // INSTEAD OF triggers handle writes correctly — the type inference
  // is what's wrong, not the actual SQL.
  //
  // TODO after Phase C frontend rewrite: remove ignoreBuildErrors and
  // migrate the remaining ~50 type sites to query rankora_* tables
  // directly with account_id filters instead of legacy compat views.
  typescript: {
    ignoreBuildErrors: true,
  },
  async headers() {
    return [
      {
        source: "/:path*",
        headers: [
          {
            key: "Strict-Transport-Security",
            value: "max-age=63072000; includeSubDomains; preload",
          },
          { key: "X-Frame-Options", value: "DENY" },
          { key: "X-Content-Type-Options", value: "nosniff" },
          {
            key: "Referrer-Policy",
            value: "strict-origin-when-cross-origin",
          },
          {
            key: "Permissions-Policy",
            value: "camera=(), microphone=(), geolocation=()",
          },
          { key: "X-DNS-Prefetch-Control", value: "on" },
        ],
      },
    ];
  },
};

// Sentry build-time wrapper. Uploads source maps to Sentry when
// SENTRY_AUTH_TOKEN is set; otherwise runs as a no-op wrapper so
// builds don't fail in local dev or when the token is absent.
// Note: `disableLogger` and `automaticVercelMonitors` were moved
// under `webpack.*` in @sentry/nextjs v10; since we're on Turbopack
// we omit them — Sentry's own debug logs are already suppressed by
// the `silent` flag during CI builds.
export default withSentryConfig(nextConfig, {
  org: process.env.SENTRY_ORG,
  project: process.env.SENTRY_PROJECT || "rankora",
  silent: !process.env.CI,
  widenClientFileUpload: true,
});

