/**
 * App environment stage — distinct from NODE_ENV.
 *
 * NODE_ENV is always "production" on Railway (controls Next.js optimizations).
 * APP_ENV tells our code which deployment stage is running:
 *   "develop"  — dev Railway deploy (verbose errors, debug banner)
 *   "staging"  — QA / pre-release
 *   "main"     — production (real users)
 *   "local"    — fallback when running locally without the var set
 */

type AppEnv = "develop" | "staging" | "main" | "local";

export const APP_ENV: AppEnv =
  (process.env.NEXT_PUBLIC_APP_ENV as AppEnv) || "local";

/** True on develop or local — use for debug banners, verbose logging, etc. */
export const isDev = APP_ENV === "develop" || APP_ENV === "local";

/** True only on staging */
export const isStaging = APP_ENV === "staging";

/** True only on main (real users, real data) */
export const isProduction = APP_ENV === "main";

/** True on any Railway deployment (not local) */
export const isDeployed = APP_ENV !== "local";

