"use client";

import { Suspense, lazy } from "react";
import { useAuth } from "@/hooks/useAuth";

const Index = lazy(() => import("@/legacy-pages/Index"));
const LandingPage = lazy(() => import("@/components/LandingPage"));

const PageLoader = () => (
  <div className="flex h-svh w-full items-center justify-center bg-background">
    <div className="h-8 w-8 animate-pulse rounded-full bg-muted" />
  </div>
);

/**
 * Client shell for "/". Receives `initialIsAuthed` from the server so
 * the first paint already renders the correct component (no flash).
 * After hydration, reconciles with the live client auth state in case
 * the user logged out in another tab or the server cookie was stale.
 */
export default function HomeClient({
  initialIsAuthed,
}: {
  initialIsAuthed: boolean;
}) {
  const { user, loading } = useAuth();

  // Before the client auth context has hydrated, trust the server signal.
  // After hydration, use the live user value.
  const isAuthed = loading ? initialIsAuthed : !!user;

  return (
    <Suspense fallback={<PageLoader />}>
      {isAuthed ? <Index /> : <LandingPage />}
    </Suspense>
  );
}

