import { NextResponse, type NextRequest } from "next/server";
import { updateSession } from "@/integrations/supabase/middleware";

// Next.js 16 renamed the `middleware` convention to `proxy`. The exported
// function name should now be `proxy` (though `middleware` still works
// with a deprecation warning). See:
// https://nextjs.org/docs/messages/middleware-to-proxy

// Routes that require an authenticated user. Unauthenticated visitors
// are redirected to /auth.
const PROTECTED_PREFIXES = [
  "/jobs",
  "/profile",
  "/billing",
  "/settings",
  "/team",
  "/tasks",
  "/activity",
  "/career-settings",
  "/integrations",
  "/reports",
  "/agency",
  "/talent-pool",
  "/sequences",
] as const;

// Admin-only routes. Non-admin visitors are redirected to /.
// Admin role verification happens in the page's own layout via
// requireAdmin() since middleware can't query user_roles without a
// round-trip that would slow every request.
const ADMIN_PREFIXES = ["/admin"] as const;

function isProtectedPath(pathname: string): boolean {
  return PROTECTED_PREFIXES.some(
    (prefix) => pathname === prefix || pathname.startsWith(`${prefix}/`),
  );
}

function isAdminPath(pathname: string): boolean {
  return ADMIN_PREFIXES.some(
    (prefix) => pathname === prefix || pathname.startsWith(`${prefix}/`),
  );
}

export async function proxy(request: NextRequest) {
  const { supabaseResponse, user } = await updateSession(request);

  const { pathname } = request.nextUrl;

  // Block unauthenticated access to protected + admin routes
  if ((isProtectedPath(pathname) || isAdminPath(pathname)) && !user) {
    const redirectUrl = request.nextUrl.clone();
    redirectUrl.pathname = "/auth";
    redirectUrl.searchParams.set("next", pathname);
    const redirectResponse = NextResponse.redirect(redirectUrl);
    // Forward any refreshed auth cookies from updateSession onto the
    // redirect response so a just-expired session doesn't force a
    // full re-login on the next request.
    supabaseResponse.cookies.getAll().forEach((cookie) => {
      redirectResponse.cookies.set(cookie);
    });
    return redirectResponse;
  }

  return supabaseResponse;
}

export const config = {
  matcher: [
    /*
     * Match all request paths except:
     * - _next/static (static assets)
     * - _next/image (image optimization)
     * - favicon.ico
     * - images, fonts, and other public static files
     */
    "/((?!_next/static|_next/image|favicon.ico|.*\\.(?:svg|png|jpg|jpeg|gif|webp|ico|woff|woff2|ttf|otf)$).*)",
  ],
};

