"use client";

import { useEffect, useCallback } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import { useAuth } from "@/hooks/useAuth";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Zap } from "lucide-react";
import { toast } from "sonner";
import AuthForm from "@/components/AuthForm";

const Auth = () => {
  const { user, loading } = useAuth();
  const router = useRouter();
  const searchParams = useSearchParams();
  const inviteToken = searchParams?.get("invite") ?? null;
  // Open-redirect protection: only allow same-origin paths starting with
  // a single "/" (not "//" or "/\" which can become protocol-relative).
  const rawNext = searchParams?.get("next") ?? "/";
  const nextPath = /^\/(?![/\\])/.test(rawNext) ? rawNext : "/";

  const acceptInvite = useCallback(async (token: string) => {
    try {
      const { data: { session } } = await supabase.auth.getSession();
      if (!session?.access_token) return;

      const res = await fetch(
        `${process.env.NEXT_PUBLIC_SUPABASE_URL}/functions/v1/accept-team-invite`,
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            "Authorization": `Bearer ${session.access_token}`,
            "apikey": process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY ?? "",
          },
          body: JSON.stringify({ token }),
        }
      );

      const json = await res.json();
      if (res.ok && json.success) {
        toast.success(`Joined team: ${json.team_name ?? "Team"}`);
        router.replace("/team");
        return;
      }
    } catch {
      // Silently fail — user can accept invite manually later
    }
    router.replace(nextPath);
  }, [router, nextPath]);

