import { redirect } from "next/navigation";
import { createClient } from "@/integrations/supabase/server";

/**
 * Server-side guard for protected pages. Call at the top of a Server
 * Component page.tsx or layout.tsx. Redirects to /auth if no session.
 *
 * This is a second line of defense — the Next.js proxy (root proxy.ts)
 * is the first gate and should redirect before the RSC even runs. This
 * helper also returns the user so pages can use it directly.
 */
export async function requireUser() {
  const supabase = await createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();

  if (!user) {
    redirect("/auth");
  }
  return user;
}

/**
 * Server-side guard for admin-only pages. Verifies both session AND
 * admin role via user_roles table.
 */
export async function requireAdmin() {
  const supabase = await createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();

  if (!user) {
    redirect("/auth");
  }

  const { data: roles } = await supabase
    .from("user_roles")
    .select("role")
    .eq("user_id", user.id);

  const isAdmin = (roles ?? []).some(
    (r: { role: string }) => r.role === "admin",
  );
  if (!isAdmin) {
    redirect("/");
  }

  return user;
}

/**
 * Optional user fetch — returns null if not logged in, does not redirect.
 * Use in pages that render different content for anon vs logged-in users.
 */
export async function getOptionalUser() {
  const supabase = await createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();
  return user;
}

