import { Suspense } from "react";
import { getOptionalUser } from "./_lib/server-auth";
import HomeClient from "./page-client";

/**
 * Server Component entry point for "/". Fetches the user server-side
 * so the first HTML response already shows the correct view (landing
 * for anon visitors, dashboard for logged-in users) with no flash.
 *
 * Only THIS page pays the Supabase getUser() cost — every other public
 * page (/changelog, /book-demo, /auth, /robots.txt, /sitemap.xml)
 * stays fully static because the root layout is synchronous.
 */
export default async function HomePage() {
  const user = await getOptionalUser();
  return (
    <Suspense fallback={null}>
      <HomeClient initialIsAuthed={!!user} />
    </Suspense>
  );
}
